    b.beads.forEach((el,i)=>{el.style.transform='translate3d('+(b.x-10.5+i*14)+'px,'+(b.z+2.5)+'px,'+(55+(mt>0&&i===count?6:0))+'px)';el.style.outline=i<count?'2px solid #fbefb7':'';});
    b.formula.textContent=count===5?'3 + 2 = 5':'3 + 2';b.formula.style.width=count===5?'87px':'58px';
    const at=result('art'),split=clamp(at/1.2);
    const heardBlue=current==='art'&&['shareBlue','shareRed'].includes(beat);
    const heardRed=current==='art'&&beat==='shareRed';
    c.left.skin.style.transform='rotate('+(7-8*(heardBlue?1:split))+'deg)';c.right.skin.style.transform='rotate('+(-8+9*(heardRed?1:split))+'deg)';
    const travel=split*split*(3-2*split);
