const deskAdventure=(()=>{
  const episodes={
    water:{speaker:'同學問',ask:'老師，我可以喝水，再去丟垃圾嗎？',reply:'可以，慢慢走。',result:'她喝完水，走去把紙屑丟進垃圾桶。',duration:3.8},
    math:{speaker:'同學問',ask:'老師，這題我不懂。你可以教我嗎？',reply:'可以，我們一起數一數。',result:'三粒紅珠，加兩粒黃珠，一共有五粒！',duration:2.2},
    art:{speaker:'兩位同學說',ask:'我想先用！',reply:'先放手，輪流說，我來聽。',result:'他們分好顏色筆，一起畫畫。',duration:1.2}
  };
  const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
  let model,bird,live=false,phase='roam',station=null,done=new Set(),history=[];
  let pos={x:478,y:0,z:62},path=[],lastDesk=null,keys=new Set();
  let frameId=0,lastTime=0,phaseTime=0,clock=0,typeTimer=0,wholeLine='',shown=0;
  let passage=null,autoPortrait=false;
  const onFollowingLeaf=()=>!$('followingLeaf').hidden;
  const solvedCount=()=>done.size+Number(phase==='result'&&!done.has(station));
  const resultPlaying=()=>phase==='result'&&!reduced()&&phaseTime<episodes[station].duration;
  const saved=()=>({phase,station,done:[...done],x:pos.x,z:pos.z,lastDesk});
  function stopText(){
    clearTimeout(typeTimer);typeTimer=0;
    if(live)readerSound.setTyping(false);
  }
  function summaryActions(){
    if(phase!=='summary')return;
    $('walkNext').hidden=Boolean(typeTimer);
    $('walkContinue').hidden=Boolean(typeTimer)||done.size===classroomMap.length;
  }
  function finishText(){stopText();shown=wholeLine.length;writeNames($('walkLine'),wholeLine);summaryActions();}
  function say(speaker,line,animate){
    stopText();wholeLine=line;shown=0;writeNames($('walkSpeaker'),speaker);
    if(!animate||reduced()){writeNames($('walkLine'),line);return;}
    const dest=$('walkLine');
    const spans=Array.from(line,c=>{const s=document.createElement('span');s.textContent=c;s.style.visibility='hidden';return s;});
    dest.replaceChildren(...spans);
    const type=()=>{
      if(!live)return;
      if(!shown)readerSound.setTyping(true);
      spans[shown++].style.visibility='visible';
      if(shown===spans.length){stopText();summaryActions();return;}
      typeTimer=setTimeout(type,90);
    };
    typeTimer=setTimeout(type,140);
  }
  const wideSpeech=matchMedia('(min-width:760px) and (min-height:510px)');
  function placePaper(){
    if(!live||onFollowingLeaf())return;
    const talking=['ask','reply','shareBlue','shareRed'].includes(phase);
    const paper=$('walkPaper'),coach=$('walkCoach'),floating=talking&&wideSpeech.matches;
    if(floating)$('walkSpeechMount').append(paper);
    else {coach.before(paper);paper.style.left='';paper.style.top='';}
    coach.hidden=!floating;coach.textContent=phase==='ask'?'如果你是老師，你會怎樣說？':phase==='reply'&&station==='art'?'聽聽他們各自需要甚麼。':'看看同學怎樣回應。';
    $('walkTry').hidden=phase!=='ask'||floating;
  }
  function render(animate=false){
    const shell=$('deskAdventure'),ep=episodes[station],next=$('walkNext');
    shell.dataset.phase=phase;shell.dataset.station=station||'';
    const count=solvedCount();
    $('visitScore').textContent=count+' / '+classroomMap.length;
    shell.querySelectorAll('.visit-tally i').forEach((el,i)=>el.classList.toggle('visited',i<count));
    let speaker='圓夢鳥',line='',action='',pose='invite';
    switch(phase){
      case 'roam':line='點有金色光邊的同學，去幫幫忙吧！';pose='observe';break;
      case 'going':line='小貢正走向同學。';break;
      case 'ask':speaker=ep.speaker;line=ep.ask;action='點小貢聽回應';pose='listen';break;
      case 'reply':speaker='小貢說';line=ep.reply;action=station==='art'?'聽聽同學':'看看同學';break;
      case 'shareBlue':speaker='一位同學說';line='我想用藍色。';action='聽另一位同學';break;
      case 'shareRed':speaker='另一位同學說';line='我想用紅色。';action='看看同學';break;
      case 'result':
        speaker=station==='math'?'同學說':'圓夢鳥';line=ep.result;pose='read';
        if(station==='art')action=autoPortrait?'':'看小貢';
        else action=count===classroomMap.length?'下一頁':'繼續探索';
        break;
      case 'closeup':line=episodes.art.result;pose='listen';break;
      case 'summary':line='現在我們終於知道為什麼老師要擅長於說話了。';pose='read';action='下一頁';break;
    }
    placePaper();
    say(speaker,line,animate&&['ask','reply','shareBlue','shareRed','summary'].includes(phase));
    $('walkSay').textContent=speaker+'。'+line+(phase==='ask'?' 請全班先試答，再點小貢。':'');
    next.hidden=!action;next.disabled=resultPlaying();writeNames(next,action);
    $('walkContinue').hidden=true;summaryActions();
    $('walkBack').disabled=!history.length;
    bird?.setPose(pose);model.pose(phase,station,done);
  }
  function transition(next,id=station,remember=true,animate=true){
    if(remember)history.push(saved());
    autoPortrait=next==='result'&&id==='art';
    phase=next;station=id;phaseTime=0;keys.clear();path=[];render(animate);
  }
  function restore(s){
    autoPortrait=false;phase=s.phase;station=s.station;done=new Set(s.done);pos={x:s.x,z:s.z,y:0};lastDesk=s.lastDesk;
    path=[];keys.clear();phaseTime=phase==='result'?10:0;render(false);
  }
  function back(){
    if(!history.length)return;
    readerSound.play('tap');restore(history.pop());
  }
  function focusTeacher(){
    history.push(saved());done.add('art');
    transition('closeup','art',false,false);
  }
  function finishEpisode(){
    if(solvedCount()===classroomMap.length){
      done.add(station);turnLeaf(true);return;
    }
    history.push(saved());done.add(station);lastDesk=station;
    readerSound.play('tap');transition('roam',null,false);
  }
  function heroAction(){
    if(phase==='ask'){
      readerSound.play('sparkle');transition('reply');return;
    }
  }
  function proceed(){
    if(phase==='summary'){if(!typeTimer)turnLeaf(true);return;}
    if(phase==='ask'){heroAction();return;}
    if(phase==='reply'){readerSound.play('tap');transition(station==='art'?'shareBlue':'result');return;}
    if(phase==='shareBlue'||phase==='shareRed'){readerSound.play('tap');transition(phase==='shareBlue'?'shareRed':'result');return;}
    if(phase==='result'){
      // Let each paper action complete, even on a quick double tap.
      if(resultPlaying())return;
      if(station==='art')focusTeacher();else finishEpisode();return;
    }
  }
  function clearSegment(a,b){
    const distance=Math.hypot(b[0]-a[0],b[1]-a[1]),n=Math.max(1,Math.ceil(distance/8));
    for(let k=1;k<=n;k++)if(model.field.why(a[0]+(b[0]-a[0])*k/n,a[1]+(b[1]-a[1])*k/n))return false;
    return true;
  }
  // Find a short route on the same walk field that blocks table legs and room boundaries.
  function route(x,z){
    const start=[pos.x,pos.z],target=[x,z],grid=24;
    if(model.field.why(x,z))return [];
    if(clearSegment(start,target))return [target];
    const key=(a,b)=>a+','+b,nearest=(v)=>Math.round(v/grid)*grid;
    const queue=[],seen=new Set(),parents=new Map();
    function add(p,from){
      const k=key(...p);if(seen.has(k)||!clearSegment(from,p))return;
      seen.add(k);parents.set(k,from);queue.push(p);
    }
    for(let i=-1;i<=1;i++)for(let j=-1;j<=1;j++)add([nearest(pos.x)+i*grid,nearest(pos.z)+j*grid],start);
    for(let k=0;k<queue.length;k++){
      const p=queue[k];
      if(clearSegment(p,target)){
        const rev=[target];let cursor=p;
        while(cursor!==start){rev.push(cursor);cursor=parents.get(key(...cursor));}
        const ordered=rev.reverse(),pruned=[];let from=start;
        for(let i=0;i<ordered.length;i++){
          if(i+1<ordered.length&&clearSegment(from,ordered[i+1]))continue;
          pruned.push(ordered[i]);from=ordered[i];
        }
        return pruned;
      }
      for(const [dx,dz] of [[0,-grid],[grid,0],[0,grid],[-grid,0]])add([p[0]+dx,p[1]+dz],p);
    }
    return [];
  }
  function visit(id){
    if(phase!=='roam'&&phase!=='going')return;
    const st=classroomMap.find(d=>d.id===id),steps=route(...st.approach);
    if(!steps.length)return;
    if(phase==='going'){station=id;phaseTime=0;render();}
    else transition('going',id);
    path=steps;readerSound.play('tap');
  }
  function floorTap(x,z){
    if(phase!=='roam')return;
    const steps=route(x,z);if(steps.length)path=steps;
  }
  function checkNearby(){
    const close=classroomMap.find(s=>{
      const dx=Math.max(0,Math.abs(pos.x-s.x)-s.w/2),dz=Math.max(0,Math.abs(pos.z-s.z)-s.d/2);
      return pos.z>s.z-s.d/2-6&&Math.hypot(dx,dz)<28;
    });
    if(!close){lastDesk=null;return;}
    if(close.id!==lastDesk){
      transition('ask',close.id);lastDesk=close.id;readerSound.play('tap');
    }
  }
  function tick(now){
    if(!live||onFollowingLeaf()||document.hidden)return;
    const elapsed=Math.max(0,(now-(lastTime||now))/1000);
    const dt=Math.min(.12,elapsed);lastTime=now;
    if(!$('audioPanel').hidden||$('contentsDialog').open){keys.clear();frameId=requestAnimationFrame(tick);return;}
    phaseTime+=elapsed;clock+=dt;
    if(phase==='result'&&autoPortrait&&phaseTime>=episodes.art.duration+.9)focusTeacher();
    const prevX=pos.x,prevZ=pos.z;
    let speed=340,dx=0,dz=0;
    if(keys.size&&phase==='roam'){
      dx=Number(keys.has('ArrowRight'))-Number(keys.has('ArrowLeft'));
      dz=Number(keys.has('ArrowDown'))-Number(keys.has('ArrowUp'));speed=240;
    }else if(path.length){
      const [x,z]=path[0];dx=x-pos.x;dz=z-pos.z;
      const dist=Math.hypot(dx,dz);speed=Math.min(speed,dist/Math.max(.000001,dt));
      if(dist<1.1){path.shift();dx=dz=0;}
    }
    const length=Math.hypot(dx,dz);
    if(length)model.field.move(pos,dx/length*dt*speed,dz/length*dt*speed);
    if(!path.length&&phase==='going'){
      lastDesk=station;transition('ask',station,false);readerSound.play('tap');
    }else if(phase==='roam'&&length)checkNearby();
    $('walkNext').disabled=resultPlaying();
    model.frame(pos,pos.x-prevX,pos.z-prevZ,dt,clock,phaseTime,done);
    if(phase==='closeup'&&(reduced()||phaseTime>=teacherZoomDuration))transition('summary',station,false);
    frameId=requestAnimationFrame(tick);
  }
  function enterWorld(){
    if(live||!classroom.active)return;
    live=true;classroom.showGuide(false);document.body.classList.add('exploring');$('deskAdventure').hidden=false;
    $('stage').setAttribute('aria-label','課室探索');$('careerSpread').setAttribute('aria-labelledby','exploreTitle');
    if(!model){
      model=makeClassroomModel(EXPLORE_ART,floorTap);
      model.startFold();
      bird=makeReadingBird($('exploreBird'),images.companion,()=>live&&!onFollowingLeaf()&&!document.hidden);
    }
    model.fit();
    lastTime=0;render();bird.sync(true);
    model.frame(pos,0,0,0,clock,phaseTime,done);frameId=requestAnimationFrame(tick);
  }
  function finishPassage({enter=true,interrupted=true}={}){
    if(!passage)return;
    if(interrupted)readerSound.stop('dreamEntry');
    const {animations,previousTransform,previousScale,sizer,focus}=passage;
    try {
      if(enter&&!passage.arrived){passage.arrived=true;passage.arrive();}
    } finally {
      for(const animation of animations){animation.onfinish=null;animation.cancel();}
      sizer.style.transform=previousTransform;
      sizer.style.scale=previousScale;
      $('dreamPortal').close();delete $('dreamPortal').dataset.part;
      document.body.classList.remove('dreaming');passage=null;
      if(enter)focus.focus({preventScroll:true});
    }
  }
  function enterDream(options){
    if(passage||(!options&&(live||!classroom.active||$('classroomSpread').dataset.step!=='discuss')))return;
    const {scene,sizer,faceNode,arrive,focus,label}=options||{
      scene:$('classScene'),sizer:$('classSizer'),faceNode:$('classDreamFace'),arrive:enterWorld,focus:$('exploreTitle'),label:'進入小貢的想像世界'
    };
    const portal=$('dreamPortal');portal.setAttribute('aria-label',label);
    const veil=portal.querySelector('.dream-veil'),quiet=reduced();
    const approach=quiet?150:2150,arrival=quiet?170:1050;
    passage={animations:[],previousTransform:sizer.style.transform,previousScale:sizer.style.scale,sizer,arrive,arrived:false,focus};
    const animation=(node,frames,options)=>{
      const clip=node.animate(frames,{fill:'forwards',...options});
      passage.animations.push(clip);return clip;
    };
    // Keep the current projected pose even if the observation camera is still settling.
    const pose=getComputedStyle(sizer);
    const currentPose=pose.transform,currentScale=pose.scale;
    document.body.classList.add('dreaming');
    sizer.style.transform=currentPose;
    sizer.style.scale=currentScale;
    portal.style.setProperty('--approach',approach+'ms');
    portal.style.setProperty('--arrival',arrival+'ms');
    portal.dataset.part='approach';portal.showModal();
    readerSound.play('dreamEntry');
    if(!quiet){
      const origin=scene.getBoundingClientRect(),face=faceNode.getBoundingClientRect();
      const width=portal.clientWidth,height=portal.clientHeight;
      const scale=Math.min(10,Math.max(1.3,Math.min(width*.47/Math.max(1,face.width),height*.44/Math.max(1,face.height))));
      const x=width*.5-origin.left-scale*(face.left+face.width/2-origin.left);
      const y=height*.46-origin.top-scale*(face.top+face.height/2-origin.top);
      // The translation above is measured from the scene's top-left in viewport space.
      // Use that same pivot even for spreads whose ordinary CSS origin is the center.
      animation(scene,[{transformOrigin:'0 0',transform:'none'},{transformOrigin:'0 0',transform:`translate3d(${x}px,${y}px,0) scale(${scale})`}],
        {duration:1810,easing:'cubic-bezier(.44,0,.22,1)'});
    }
    const fadeIn=animation(veil,[{opacity:0},{opacity:0,offset:quiet?0:.51},{opacity:1}],
      {duration:approach,easing:'linear'});
    fadeIn.onfinish=()=>{
      // Both rooms are hidden by opaque paper at this single hand-off.
      passage.arrived=true;arrive();
      portal.dataset.part='arrival';
      const fadeOut=animation(veil,[{opacity:1},{opacity:1,offset:quiet?0:.11},{opacity:0}],
        {duration:arrival,easing:'ease-out'});
      fadeOut.onfinish=()=>finishPassage({interrupted:false});
    };
  }
  function close(){
    if(!live)return;
    if(phase==='going'&&history.length)restore(history.pop());
    if(phase==='closeup')transition('summary',station,false,false);
    lokSpread.leave();stopText();live=false;keys.clear();path=[];cancelAnimationFrame(frameId);bird.sync(false);
    $('followingLeaf').hidden=true;$('deskAdventure').hidden=true;document.body.classList.remove('exploring');classroom.showGuide(true);
    $('stage').setAttribute('aria-label','小貢的教室互動立體書');$('careerSpread').setAttribute('aria-labelledby','classTitle');
    readerSound.play('page');$('exploreLaunch').focus({preventScroll:true});
  }
  function returnToDiscussion(){
    close();classroom.showDiscussion();$('exploreLaunch').focus({preventScroll:true});
  }
  function turnLeaf(forward){
    if(!live||forward===onFollowingLeaf())return;
    keys.clear();cancelAnimationFrame(frameId);
    if(forward&&typeTimer)finishText();
    $('followingLeaf').hidden=!forward;$('deskAdventure').hidden=forward;
    const title=forward?$('followingTitle'):$('exploreTitle');
    $('stage').setAttribute('aria-label',title.textContent);
    $('careerSpread').setAttribute('aria-labelledby',title.id);
    if(forward)lokSpread.enter();else lokSpread.leave();
    bird.sync(!forward);readerSound.play('page');
    if(!forward){
      model.fit();lastTime=0;frameId=requestAnimationFrame(tick);
    }
    requestAnimationFrame(()=>{
      if(live&&!lokChapter.active&&onFollowingLeaf()===forward&&$('audioPanel').hidden&&!$('contentsDialog').open){
        (forward||$('walkNext').hidden?title:$('walkNext')).focus({preventScroll:true});
      }
    });
  }
  function reset(){
    if(passage)finishPassage({enter:false});
    if(live)close();lokSpread.reset();lokChapter.reset();autoPortrait=false;phase='roam';station=null;done.clear();history=[];pos={x:478,y:0,z:62};
    model?.startFold();
    path=[];keys.clear();lastDesk=null;phaseTime=0;
  }
  function bind(){
    lokSpread.bind(()=>turnLeaf(false),()=>lokChapter.open('cards'));
    $('exploreLaunch').onclick=()=>enterDream();
    $('dreamSkip').onclick=()=>finishPassage();
    $('dreamPortal').addEventListener('cancel',e=>{e.preventDefault();finishPassage();});
    window.addEventListener('resize',()=>{if(passage)finishPassage();});
    $('walkContinue').onclick=()=>{
      if(phase==='summary'&&!typeTimer&&done.size<classroomMap.length)finishEpisode();
    };
    $('walkExit').onclick=returnToDiscussion;$('walkBack').onclick=back;
    $('walkHero').onclick=heroAction;$('walkNext').onclick=proceed;
    $('walkLine').onclick=()=>{if(typeTimer)finishText();};
    wideSpeech.addEventListener('change',placePaper);
    for(const btn of $('walkTargets').querySelectorAll('[data-desk]'))btn.onclick=()=>visit(btn.dataset.desk);
    document.addEventListener('keydown',e=>{
      if(passage||lokChapter.active||!live||e.defaultPrevented||$('comparison').open||!$('audioPanel').hidden||e.altKey||e.metaKey||e.ctrlKey)return;
      if(onFollowingLeaf()){
        if(!e.shiftKey&&e.key==='ArrowRight'){e.preventDefault();if(!e.repeat)lokChapter.open('cards');return;}
        if(!e.shiftKey&&(e.key==='ArrowLeft'||e.key==='Escape')){e.preventDefault();if(!e.repeat)turnLeaf(false);}
        return;
      }
      if(e.key==='ArrowRight'&&!$('walkNext').hidden&&(phase==='summary'||(phase==='result'&&solvedCount()===classroomMap.length))){
        e.preventDefault();if(!e.repeat)proceed();return;
      }
      if(e.key==='Escape'){e.preventDefault();returnToDiscussion();return;}
      if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))return;
      e.preventDefault();if(phase==='roam'){path=[];keys.add(e.key);}
    });
    document.addEventListener('keyup',e=>keys.delete(e.key));
    window.addEventListener('blur',()=>keys.clear());
    document.addEventListener('visibilitychange',()=>{
      if(!live||onFollowingLeaf())return;
      keys.clear();cancelAnimationFrame(frameId);lastTime=0;
      if(document.hidden){if(typeTimer)finishText();bird.sync(false);}
      else{bird.sync(true);frameId=requestAnimationFrame(tick);}
    });
  }
  function jumpIn(){
    enterWorld();
    $('exploreTitle').focus({preventScroll:true});
  }
  return {get active(){return live||Boolean(passage);},bind,reset,enterDream,jumpIn,close,turnLeaf};
})();


const lokChapter=(()=>{
  const roles=[
    {key:'reception',name:'酒店接待員',image:'hotel',detail:'微笑着歡迎住客。'},
    {key:'clown',name:'小丑',image:'clown',scene:'tent',detail:'用有趣的表演逗大家笑。'},
    {key:'retail',name:'服裝銷售員',image:'shop',detail:'幫客人挑選合適的衣服。'}
  ];
  const foodRoles=[
    {key:'creator',name:'美食網紅',image:'creator',detail:'拍影片，介紹好吃的點心。'},
    {key:'nutrition',name:'食品營養師',image:'nutrition',detail:'幫大家配搭均衡的一餐。'},
    {key:'chef',name:'廚師',image:'foodChef',scene:'foodKitchen',detail:'把食材變成美味的菜餚。'}
  ];
  let foodHand, filmBird;
  function prepareFoodHand(){
    if(foodHand)return;
    $('tungDeck').style.setProperty('--dream-print','url("'+CAREER_ART.careerBack+'")');
    foodHand=makeGuessHand({roles:foodRoles,art:TUNG_ART,pupil:'東東',hand:$('tungHand'),countLabel:$('tungCount'),
      resetButton:$('tungReguess'),invite:$('tungInvite'),status:$('circusStatus'),visible:()=>page==='tung-cards'});
  }
  const props={hat:'魔術帽',drum:'小鼓',ball:'波點球'};
  const quote='「我要做小丑，使人人都開開心心。」';
  const steps=['intro','speech','observe','discuss'];
  const quiet=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
  const limit=(n,min,max)=>Math.max(min,Math.min(n,max));
  let page='',fromStory=false,step=0,hand,bird,scanBefore,viewBefore;
  let lines=[],letterTimer=0,read=true,seenProp='',drag=null,blockClick=false,frame=0;
  let pitch=50,yaw=0,zoom=100,locked=false;
  const inShow=()=>page==='play';
  const inRing=()=>page==='circus';
  function announce(text){$('circusStatus').textContent=text;}
  function stopLetters(){
    clearTimeout(letterTimer);letterTimer=0;readerSound.setTyping(false);
    for(const span of lines)span.style.visibility='visible';lines=[];
  }
  function finishLine(){
    stopLetters();read=true;
    if(page==='circus'&&step===1){$('circusBird').disabled=false;$('circusName').hidden=false;}
  }
  function showLine(animate){
    stopLetters();const dest=$('circusWords');dest.textContent=quote;
    $('circusSpeech').setAttribute('aria-label','樂樂說。'+quote+' 點一下顯示整句。');
    if(!animate||quiet()){finishLine();return;}
    read=false;dest.replaceChildren();
    lines=Array.from(quote,c=>{const n=document.createElement('span');n.textContent=c;n.style.visibility='hidden';dest.append(n);return n;});
    let at=0;
    function type(){
      if(!at)readerSound.setTyping(true);
      lines[at++].style.visibility='visible';
      if(at===lines.length)finishLine();else letterTimer=setTimeout(type,95);
    }
    letterTimer=setTimeout(type,160);
  }
  function setupArt(){
    $('lokChapter').style.backgroundImage=$('careerSpread').style.backgroundImage||'url("'+wood().toDataURL('image/jpeg',.82)+'")';
    $('lokDeck').style.setProperty('--dream-print','url("'+CAREER_ART.careerBack+'")');
    hand=makeGuessHand({roles,art:CIRCUS_ART,pupil:'樂樂',hand:$('lokHand'),countLabel:$('circusProgress'),resetButton:$('lokReguess'),
      invite:$('lokCardsInvite'),status:$('circusStatus'),visible:()=>page==='cards'});
    for(const img of $('circusBook').querySelectorAll('[data-ring]'))img.src=CIRCUS_ART[img.dataset.ring];
    $('circusBook').style.setProperty('--ring-paper','url("'+CIRCUS_ART.wall+'")');
    const flags=$('circusBook').querySelector('.circus-flags canvas');
    const ctx=flags.getContext('2d');
    const colours=['#f5c456','#d47880','#5d9f99','#ad7f9b'];
    const cord=x=>9+67*Math.sin(Math.PI*x/flags.width);
    ctx.beginPath();
    for(let x=0;x<=flags.width;x+=4){
      if(x===0)ctx.moveTo(x,cord(x));else ctx.lineTo(x,cord(x));
    }
    ctx.lineWidth=5;ctx.strokeStyle='#846a55';ctx.stroke();
    for(let i=0;i<11;i++){
      const x=(i+.49)*flags.width/11,y=cord(x);
      ctx.beginPath();ctx.moveTo(x-42,cord(x-42));ctx.lineTo(x+42,cord(x+42));
      ctx.lineTo(x+10*Math.cos(i),y+83+(i%3)*7);ctx.closePath();
      ctx.fillStyle=colours[i%colours.length];ctx.fill();
    }
    bird=makeReadingBird($('circusBirdCanvas'),images.companion,()=>inRing()&&!document.hidden&&!$('comparison').open);
  }
  function controls(){
    const btn=$('bestView');btn.setAttribute('aria-pressed',String(locked));btn.querySelector('span').textContent=locked?'解除鎖定':'固定最佳視角';
    btn.querySelector('use').setAttribute('href',locked?'#camera-locked':'#camera-best');btn.title=locked?'解除視角鎖定':'回到並固定最佳視角';btn.setAttribute('aria-label',btn.title);
    $('circusScene').toggleAttribute('data-locked',locked);$('circusZoom').textContent=zoom+'%';$('circusOut').disabled=zoom<=70;$('circusIn').disabled=zoom>=160;
  }
  function placeSpeech(){
    const card=$('circusSpeech');if(!inRing()||card.hidden)return;
    const scene=$('circusScene').getBoundingClientRect(),face=$('circusFace').getBoundingClientRect(),w=card.offsetWidth,h=card.offsetHeight;
    const cx=(face.left+face.right)*.5-scene.left,top=face.top-scene.top;
    let side='',x=cx-w*.72,y=top-h-10;
    if(y<3){
      if(face.left-scene.left-w>15){side='left';x=face.left-scene.left-w-14;}
      else if(scene.right-face.right-w>15){side='right';x=face.right-scene.left+14;}
      if(side)y=top-h*.45;
    }
    x=limit(x,6,scene.width-w-6);
    card.dataset.side=side;card.style.left=x+'px';card.style.top=limit(y,3,scene.height-h-4)+'px';card.style.setProperty('--tip',limit(cx-x,12,w-16)+'px');
  }
  function placeLabels(){
    placeSpeech();
    const label=$('circusPropLabel');
    if(label.hidden)return;
    const bounds=$('circusScene').getBoundingClientRect();
    const prop=$('circusBook').querySelector('[data-act="'+seenProp+'"]').getBoundingClientRect();
    const cx=(prop.left+prop.right)/2-bounds.left,w=label.offsetWidth,h=label.offsetHeight;
    const x=limit(cx-w/2,6,bounds.width-w-6),above=prop.top-bounds.top-h-9;
    const below=above<5;
    label.toggleAttribute('data-below',below);
    label.style.left=x+'px';
    label.style.top=limit(below?prop.bottom-bounds.top+9:above,5,bounds.height-h-6)+'px';
    label.style.setProperty('--tip',limit(cx-x,12,w-12)+'px');
    label.style.visibility=prop.bottom<bounds.top||prop.top>bounds.bottom||prop.right<bounds.left||prop.left>bounds.right?'hidden':'visible';
  }
  function followLabels(){
    if(frame||($('circusSpeech').hidden&&$('circusPropLabel').hidden))return;
    const tick=()=>{
      frame=0;
      if(!inRing()||($('circusSpeech').hidden&&$('circusPropLabel').hidden))return;
      placeLabels();
      if($('circusSizer').getAnimations({subtree:true}).some(a=>a.playState==='running'))frame=requestAnimationFrame(tick);
    };
    frame=requestAnimationFrame(tick);
  }
  function size(){
    if(!inRing())return;
    const scene=$('circusScene'),sizer=$('circusSizer'),narrow=scene.clientWidth<590,looking=step===2;
    const unit=Math.min(scene.clientWidth/1160,scene.clientHeight/575);
    const scale=unit*zoom/100*(looking?(narrow?1.55:1.2):1);
    sizer.style.setProperty('--ring-scale',scale);sizer.style.setProperty('--ring-pan',(looking?-140*scale:0)+'px');
    sizer.style.setProperty('--ring-dy',(looking?-4:-10)*scale+'px');
    $('circusBook').style.setProperty('--ring-yaw',yaw+'deg');$('circusBook').style.setProperty('--ring-pitch',pitch+'deg');
    $('circusBook').style.setProperty('--ring-hit',Math.ceil(46/Math.max(.15,scale))+'px');
    placeLabels();followLabels();
  }
  function bestView(){if(!inRing())return;locked=!locked;if(locked){zoom=100;pitch=50;yaw=0;}readerSound.play('tap');controls();size();}
  function changeZoom(n){zoom=limit(n,70,160);controls();size();}
  function turn(dx,dy){if(!locked){yaw=limit(yaw+dx,-25,25);pitch=limit(pitch+dy,36,62);size();}}
  function focusTitle(){
    const which=page==='cards'?'lokCardsTitle':inShow()?'filmTitle':page==='tung-question'?'tungTitle':page==='tung-cards'?'tungCardsTitle':'circusTitle';
    $('lokChapter').setAttribute('aria-labelledby',which);$(which).focus({preventScroll:true});
  }
  function render(animate=false){
    if(!inRing())return;
    const s=steps[step],talk=s==='speech',observing=s==='observe',discuss=s==='discuss';
    $('circusLeaf').dataset.step=s;
    $('circusHero').disabled=step!==0;$('circusName').hidden=step===0||(talk&&animate&&!quiet());
    $('circusDiscuss').hidden=!discuss;$('circusBird').querySelector('.circus-ticket').hidden=discuss;
    const label=$('circusPropLabel');
    label.hidden=!(observing&&seenProp);
    label.textContent=label.hidden?'':props[seenProp];
    $('circusSpeech').hidden=!talk;
    if(talk)showLine(animate);
    else {stopLetters();read=true;}
    const cue=['讀一讀','讀完對白，點點我','觀察一下 · 說完點我繼續',''][step];
    const prompt=['點樂樂，聽他說出志願','一起觀察','看看樂樂身邊的道具，你猜他會怎樣逗大家笑？',''][step];
    const pose=['listen','invite','observe','read'][step];
    for(const b of $('circusBook').querySelectorAll('[data-act]')){
      const key=b.dataset.act;b.disabled=!observing;b.setAttribute('aria-label',props[key]);
      if(observing)b.dataset.glow='silver';else delete b.dataset.glow;
      if(observing)b.setAttribute('aria-pressed',String(seenProp===key));else b.removeAttribute('aria-pressed');
    }
    writeNames($('circusCue'),cue);writeNames($('circusPrompt'),prompt);
    $('circusBird').disabled=!(observing||(talk&&read));
    $('circusBird').setAttribute('aria-label','圓夢鳥。'+(discuss?'想一想':cue+'。'+prompt));
    bird.setPose(pose);$('circusProgress').textContent=['聽樂樂說','讀對白','一起觀察','想一想'][step];
    $('circusUndo').disabled=step===0;
    $('circusNext').hidden=true;
    if(talk)announce('樂樂說。'+quote);else announce(discuss?$('circusDiscuss').textContent:prompt);
    size();
  }
  function setPage(next,sound=true){
    const old=page;if(laterBook.has(old))laterBook.leave();if(old==='play')resetFilm();
    if(old==='tung-question')tungSpread.leave();
    stopLetters();drag=null;blockClick=false;page=next;
    $('lokChapter').classList.toggle('later-active',laterBook.has(next));
    if(laterBook.has(next)){
      document.body.classList.toggle('lok-cards',laterBook.isActivity(next));bird.sync(false);laterBook.enter(next);if(sound)readerSound.play('page');return;
    }
    const cards=page==='cards',question=page==='tung-question',food=page==='tung-cards',play=inShow();
    document.body.classList.toggle('lok-cards',cards||food||play);
    $('circusCinema').hidden=!play;
    $('lokDeck').hidden=!cards;$('tungLeaf').hidden=!question;$('tungDeck').hidden=!food;
    $('tungCardFooter').hidden=!food;document.querySelector('.circus-footer').hidden=question||food;$('circusLeaf').hidden=!inRing();
    $('circusZoomTools').hidden=!inRing();$('lokReguess').hidden=!cards;$('circusUndo').hidden=!inRing();
    $('circusNext').hidden=!cards;$('circusNext').textContent='下一頁';
    const prev=$('circusPrev');
    writeNames(prev,cards?(fromStory?'上一頁':'返回封面'):play?'返回想一想':'職業猜想');

    if(cards){
      const n=$('lokHand').querySelectorAll('[aria-pressed="true"]').length;
      $('circusProgress').textContent=n+' / 3';
      announce('樂樂的職業猜想。先猜一猜，再翻卡。');
    }else if(play){
      resetFilm();$('circusProgress').textContent='馬戲團放映室';announce('短片準備好了，點播放影片開始。');
    }else if(question){tungSpread.enter();}
    else if(food){prepareFoodHand();announce('東東的職業猜想。先猜一猜，再翻卡。');}
    else {
      $('scan').src=CIRCUS_ART.page6;$('scan').alt='原書第 6 頁，樂樂裝扮成小丑，和白兔、小馬、藍象一起表演。';$('comparisonTitle').lastChild.textContent='原書對照 · 第 6 頁';
      controls();render();const leaf=$('circusLeaf');leaf.classList.remove('rising');
      if(old==='cards'){void leaf.offsetWidth;leaf.classList.add('rising');}
    }
    bird.sync(inRing());if(sound)readerSound.play('page');focusTitle();
  }
  function open(target='cards'){
    if(page)return;
    fromStory=lokSpread.active;
    if(fromStory)lokSpread.leave();
    const scan=$('scan'),best=$('bestView');
    scanBefore=[scan.src,scan.alt,$('comparisonTitle').lastChild.textContent];
    viewBefore=[best.title,best.getAttribute('aria-label'),best.getAttribute('aria-pressed'),best.querySelector('span').textContent,best.querySelector('use').getAttribute('href')];
    document.body.classList.add('lok-chapter-active');$('lokChapter').hidden=false;
    if(!hand)setupArt();
    setPage(target,fromStory);
    if(target==='circus'){void $('circusLeaf').offsetWidth;$('circusLeaf').classList.add('rising');}
  }
  function close(){
    if(!page)return;
    if(laterBook.has(page)){laterBook.leave();$('lokChapter').classList.remove('later-active');}
    if(inShow())resetFilm();
    if(page==='tung-question')tungSpread.leave();
    stopLetters();bird.sync(false);page='';$('lokChapter').hidden=true;
    document.body.classList.remove('lok-chapter-active','lok-after','lok-cards');
    const best=$('bestView');best.title=viewBefore[0];best.setAttribute('aria-label',viewBefore[1]);best.setAttribute('aria-pressed',viewBefore[2]);best.querySelector('span').textContent=viewBefore[3];best.querySelector('use').setAttribute('href',viewBefore[4]);
    $('scan').src=scanBefore[0];$('scan').alt=scanBefore[1];$('comparisonTitle').lastChild.textContent=scanBefore[2];
    readerSound.play('page');
    if(fromStory){lokSpread.enter();$('lokNext').focus({preventScroll:true});}
    else {
      if(['#lok-cards','#lok-circus'].includes(location.hash))history.replaceState(null,'',location.pathname+location.search);
      fit();$('turn').focus({preventScroll:true});
    }
  }
  function back(){
    if(page==='cards')close();
    else if(page==='circus')setPage('cards');
    else if(inShow()){step=3;setPage('circus');}
    else if(page==='tung-question')setPage('play');
    else if(page==='tung-cards')setPage('tung-question');
  }
  function next(){
    if(page==='cards'){setPage('circus');return;}
    if(page==='tung-question'){setPage('tung-cards');return;}
    if(inShow()&&!$('circusNext').hidden)setPage('tung-question');
  }
  function advanceStep(n,animate=false){
    if(page!=='circus'||n<0||n>=steps.length)return;
    step=n;seenProp='';readerSound.play(animate?'sparkle':'tap');render(animate);
  }
  function startShow(){
    if(page!=='circus'||step!==3)return;
    deskAdventure.enterDream({scene:$('circusScene'),sizer:$('circusSizer'),faceNode:$('circusFace'),arrive:()=>setPage('play',false),focus:$('filmStart'),label:'進入樂樂的想像世界'});
  }
  function reset(){if(page)close();step=0;zoom=100;pitch=50;yaw=0;locked=false;seenProp='';if(hand)hand.reset();tungSpread.reset();foodHand?.reset();}
  function showFilmSummary(visible){
    const card=$('filmSummary');
    card.hidden=!visible;
    $('circusNext').hidden=!visible;
    if(visible&&!filmBird){
      filmBird=makeReadingBird($('filmBird'),images.companion,()=>inShow()&&!card.hidden);
      filmBird.setPose('read');
    }
    filmBird?.sync(visible);
  }
  function exitFilmScreen(){
    const frame=$('filmFrame'),video=$('circusFilm');
    frame.classList.remove('is-projecting');
    video.controlsList?.remove('nofullscreen');
    if(document.fullscreenElement===frame||document.fullscreenElement===video){
      document.exitFullscreen().catch(()=>{});
    }else if(video.webkitDisplayingFullscreen){
      video.webkitExitFullscreen?.();
    }
  }
  function enterFilmScreen(video){
    const frame=$('filmFrame'),rect=frame.getBoundingClientRect();
    frame.style.setProperty('--film-x',(rect.left+rect.width/2)+'px');
    frame.style.setProperty('--film-y',(rect.top+rect.height/2)+'px');
    frame.style.setProperty('--film-width',rect.width+'px');
    frame.classList.add('is-projecting');
    video.controlsList?.add('nofullscreen');
    if(frame.requestFullscreen){
      // Request during the play button's gesture. The same layout also fills a restricted viewport.
      frame.requestFullscreen().then(()=>{
        if(!frame.classList.contains('is-projecting')&&document.fullscreenElement===frame)exitFilmScreen();
      }).catch(()=>{});
    }
  }
  function resetFilm(){
    exitFilmScreen();
    showFilmSummary(false);
    const video=$('circusFilm');
    video.pause();video.controls=false;
    if(video.hasAttribute('src')){video.removeAttribute('src');video.load();}
    $('filmStart').hidden=false;$('filmStart').querySelector('b').textContent='播放影片';
  }
  async function playFilm(){
    if(!inShow()||$('dreamPortal').open||$('filmStart').hidden)return;
    const video=$('circusFilm');
    if(!video.hasAttribute('src'))video.src=video.dataset.source;
    showFilmSummary(false);
    if(video.ended)video.currentTime=0;
    $('filmStart').hidden=true;video.controls=true;
    try{
      const playing=video.play();
      enterFilmScreen(video);
      await playing;
      if(inShow()&&!video.paused)video.focus({preventScroll:true});
    }catch(error){
      if(!inShow()||error.name==='AbortError')return;
      resetFilm();announce('影片暫時未能播放，請再試一次。');
    }
  }
  function bind(){
    const video=$('circusFilm');
    const frame=$('filmFrame');
    $('filmStart').onclick=playFilm;
    $('filmExit').onclick=()=>{exitFilmScreen();video.focus({preventScroll:true});};
    frame.addEventListener('fullscreenchange',()=>{
      if(!document.fullscreenElement||!frame.contains(document.fullscreenElement))exitFilmScreen();
    });
    video.addEventListener('webkitendfullscreen',exitFilmScreen);
    // Older mobile players expose native fullscreen only after media begins playing.
    video.addEventListener('playing',async()=>{
      if(frame.requestFullscreen||!video.webkitEnterFullscreen||!frame.classList.contains('is-projecting'))return;
      const zoomIn=video.getAnimations().find(animation=>animation.animationName==='film-zoom-in');
      try{
        await zoomIn?.finished;
        if(frame.classList.contains('is-projecting')&&!video.paused&&!video.webkitDisplayingFullscreen)video.webkitEnterFullscreen();
      }catch{/* The viewport presentation remains available. */}
    });
    video.addEventListener('playing',()=>{if(inShow())$('filmStart').hidden=true;});
    video.addEventListener('ended',()=>{
      if(!inShow()||!video.ended)return;
      exitFilmScreen();
      video.controls=false;
      showFilmSummary(true);
      $('filmStart').hidden=false;$('filmStart').querySelector('b').textContent='再看一次';
      $('circusNext').focus({preventScroll:true});
      announce('圓夢鳥：'+$('filmSummaryLine').textContent);
    });
    document.addEventListener('visibilitychange',()=>{
      if(document.hidden&&inShow())video.pause();
      filmBird?.sync(inShow()&&!$('filmSummary').hidden);
    });
    new MutationObserver(()=>{if(inShow()&&$('contentsDialog').open)video.pause();}).observe($('contentsDialog'),{attributes:true,attributeFilter:['open']});
    tungSpread.bind(back,next);$('tungCardsBack').onclick=$('tungDeckBack').onclick=back;
    $('circusPrev').onclick=$('circusCorner').onclick=back;$('circusNext').onclick=$('deckCorner').onclick=next;
    $('circusHero').onclick=()=>{if(page==='circus'&&step===0)advanceStep(1,true);};
    $('circusSpeech').onclick=finishLine;
    $('circusBird').onclick=()=>{if(step===1||step===2)advanceStep(step+1);};
    $('circusUndo').onclick=()=>advanceStep(step-1);
    $('enterCircus').onclick=startShow;
    for(const b of $('circusBook').querySelectorAll('[data-act]'))b.onclick=()=>{
      const key=b.dataset.act;
      if(page==='circus'&&step===2){readerSound.play('tap');seenProp=seenProp===key?'':key;render();announce(seenProp?props[key]:'觀察表演道具');}
    };
    for(const [id,delta] of [['circusOut',-10],['circusIn',10],['circusZoom',0]])$(id).onclick=()=>{readerSound.play('tap');changeZoom(delta?zoom+delta:100);};
    $('tungDeckForward').onclick=$('tungCardsForward').onclick=()=>bookContents.changePage('tung-chef');
    const scene=$('circusScene');
    scene.addEventListener('wheel',e=>{if(inRing()&&e.deltaY){e.preventDefault();changeZoom(zoom-Math.sign(e.deltaY)*5);}},{passive:false});
    scene.addEventListener('pointerdown',e=>{if(e.isPrimary&&e.button===0){blockClick=false;drag={id:e.pointerId,x:e.clientX,y:e.clientY,pitch,yaw};}});
    scene.addEventListener('pointermove',e=>{
      if(!drag||drag.id!==e.pointerId)return;
      const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!blockClick&&Math.hypot(dx,dy)<8)return;
      if(!blockClick)scene.setPointerCapture(e.pointerId);
      blockClick=true;if(!locked){yaw=drag.yaw;pitch=drag.pitch;turn(dx*.09,dy*.07);}
    });
    for(const ev of ['pointerup','pointercancel','lostpointercapture'])scene.addEventListener(ev,e=>{if(drag?.id===e.pointerId)drag=null;});
    scene.addEventListener('click',e=>{if(blockClick&&e.detail){blockClick=false;e.stopPropagation();e.preventDefault();}},true);
    document.addEventListener('keydown',e=>{
      if(!page||laterBook.has(page)||$('contentsDialog').open||$('dreamPortal').open||$('comparison').open||!$('audioPanel').hidden||e.defaultPrevented||e.ctrlKey||e.altKey||e.metaKey)return;
      if(inShow()&&frame.classList.contains('is-projecting')){
        if(e.key==='Escape'){e.preventDefault();exitFilmScreen();video.focus({preventScroll:true});}
        return;
      }
      const dir={ArrowLeft:[-4,0],ArrowRight:[4,0],ArrowUp:[0,-4],ArrowDown:[0,4]}[e.key];
      if(dir&&e.shiftKey&&inRing()){e.preventDefault();turn(dir[0],-dir[1]);}
      else if(inShow()&&e.target===$('circusFilm'))return;
      else if(e.key==='Escape'||e.key==='ArrowLeft'){e.preventDefault();if(!e.repeat)back();}
      else if(e.key==='ArrowRight'&&page==='tung-cards'){e.preventDefault();if(!e.repeat)bookContents.changePage('tung-chef');}
      else if(e.key==='ArrowRight'&&(page==='cards'||page==='tung-question'||inShow())){e.preventDefault();if(!e.repeat)next();}
    });
    new ResizeObserver(size).observe(scene);$('circusSizer').addEventListener('transitionrun',followLabels);
    const sync=()=>{if(!inRing())return;if(document.hidden||$('comparison').open)finishLine();bird.sync(!document.hidden&&!$('comparison').open);};
    document.addEventListener('visibilitychange',sync);new MutationObserver(sync).observe($('comparison'),{attributes:true,attributeFilter:['open']});
  }
  return {open,close,jump:target=>setPage(target,false),reset,bind,bestView,finishLine,get page(){return page;},get active(){return Boolean(page);}};
})();

