    const done=button(actions,'完成作品',()=>{state.finished=true;readerSound.play('correct');update();again.focus({preventScroll:true});});
    const again=button(finishedRow,'繼續畫',()=>{state.finished=false;readerSound.play('tap');update();(state.erasing?eraser:crayons[state.color]).focus({preventScroll:true});});
