    mount.style.cssText=stylist.style.cssText;
    stylist.after(mount);
    const button=node('button','salon-dryer');button.type='button';button.dataset.role='dryer';
    button.disabled=true;button.setAttribute('aria-label','吹風機');button.onclick=()=>hit('dryer');
    const svgNS='http://www.w3.org/2000/svg';
    const svg=document.createElementNS(svgNS,'svg'),outline=document.createElementNS(svgNS,'path');
    svg.setAttribute('viewBox','110 216 107 114');svg.setAttribute('preserveAspectRatio','none');svg.setAttribute('aria-hidden','true');
    // The fingers cover the middle of the grip. Outline the two exposed shapes.
    outline.setAttribute('d','M116 244 Q119 231 120 228 Q121 225 126 226 L151 232 C161 223 172 220 183 222 C199 224 210 236 209 251 C209 267 199 276 185 278 L185 281 Q176 278 165 280 L165 276 Q155 270 152 259 L121 252 Q115 251 116 244 Z M164 309 Q170 312 179 313 L177 321 Q176 326 170 325 Q164 325 164 320 Z');
    svg.append(outline);button.append(svg);mount.append(button);
