const nameParts = new RegExp('('+Array.from(properNames).join('|')+')','u');
function writeNames(element,text){
 const parts=text.split(nameParts).map(part=>{
  if(!properNames.has(part))return document.createTextNode(part);
  const mark=document.createElement('u');
  mark.className='proper-name';mark.textContent=part;return mark;
 });
 element.replaceChildren(...parts);
}
