 if(fallback){
  left=fallbackPoint(.085,.825);right=fallbackPoint(.48,.85);
 }else{
  left=projectedGround(-5.10,2.39);
  right=projectedGround(-.11,2.39);
 }
 const pageWidth=right.x-left.x,foldout=width<640&&pageWidth<300;
 // A narrow book opens a wider paper tab from the same front edge.
 const room=foldout?Math.min(width*.84,pageWidth*1.85):pageWidth;
 paper.style.removeProperty('font-size');
 if(!foldout){
  const normal=parseFloat(getComputedStyle(paper).fontSize);
  paper.style.fontSize=Math.min(normal,Math.max(23,(room-5)/(narration.length+1.35)))+'px';
 }
 paper.style.width='max-content';
 paper.style.maxWidth=room+'px';
 const cx=foldout?left.x+paper.offsetWidth/2:(left.x+right.x)/2;
 const limitY=height-paper.offsetHeight/2-5;
 let nx=Math.min(width-paper.offsetWidth/2-6,Math.max(paper.offsetWidth/2+6,cx));
 let ny=Math.min(limitY,(left.y+right.y)/2+(foldout?paper.offsetHeight*.23:0));
 const cornerEdge=corner.x+$('pageCorner').offsetWidth/2+6;
 if(!$('pageCorner').hidden && Math.abs(ny-corner.y)<paper.offsetHeight/2+$('pageCorner').offsetHeight/2+3 &&
    nx-paper.offsetWidth/2<cornerEdge && nx+paper.offsetWidth/2>corner.x-27){
  if(cornerEdge+paper.offsetWidth<width-5)nx=cornerEdge+paper.offsetWidth/2;
  else ny=Math.min(ny,corner.y-$('pageCorner').offsetHeight/2-3-paper.offsetHeight/2);
 }
 const nextButton=nextCorner.button;
 if(!nextButton.hidden && Math.abs(nx-nextCorner.x)<(paper.offsetWidth+nextButton.offsetWidth)/2+4 &&
    Math.abs(ny-nextCorner.y)<(paper.offsetHeight+nextButton.offsetHeight)/2+4){
  ny=nextCorner.y-(paper.offsetHeight+nextButton.offsetHeight)/2-5;
 }
