 g.fillStyle='#ffefd1';g.fillRect(0,0,1900,1050);g.fillStyle=grad;g.beginPath();g.roundRect(20,17,1860,1000,29);g.fill();g.save();g.clip();
 g.fillStyle='#f0dfa9';g.beginPath();g.moveTo(0,140);g.bezierCurveTo(480,120,590,240,60,450);g.bezierCurveTo(-120,520,140,580,270,610);g.bezierCurveTo(-200,630,-115,580,-100,480);g.bezierCurveTo(25,321,480,238,0,222);g.fill();
 g.drawImage(images.mat,440,180,1280,650);
 for(let i=0;i<450;i++){const x=rng()*1900,y=rng()*1020;if(x>465&&x<1700&&y>220&&y<800)continue;g.strokeStyle='rgba(95,130,67,.17)';g.lineWidth=1.5;g.beginPath();g.moveTo(x-3,y-5);g.lineTo(x,y);g.lineTo(x+4,y-7);g.stroke()}
 g.restore();g.strokeStyle='#a9ac7f';g.lineWidth=1.5;g.strokeRect(14,12,1872,1023);
 g.font='italic 26px Georgia';g.fillStyle='#52623e';g.fillText('2',52,991);g.textAlign='right';g.fillText('3',1848,991);
 const seam=g.createLinearGradient(895,0,1005,0);seam.addColorStop(0,'#4c452a00');seam.addColorStop(.46,'#4c452a22');seam.addColorStop(.50,'#56492c55');seam.addColorStop(.53,'#fff4d155');seam.addColorStop(1,'#fff4d100');g.fillStyle=seam;g.fillRect(890,0,120,1050);
