 pts.forEach(a=>p.quadraticCurveTo(...a));p.lineTo(1792,533);p.closePath();g.save();g.clip(p);const skyColor=g.createLinearGradient(0,0,0,540);skyColor.addColorStop(0,'#91cdda');skyColor.addColorStop(.78,'#d8ebd5');skyColor.addColorStop(1,'#c2d8ad');g.fillStyle=skyColor;g.fillRect(0,0,1800,540);
 g.fillStyle='#ffdf8e';g.beginPath();g.arc(1335,142,54,0,2*PI);g.fill();
 function cloud(x,y,scale){g.save();g.translate(x,y);g.scale(scale,scale);g.fillStyle='#fff4db';g.beginPath();g.moveTo(-81,11);g.quadraticCurveTo(-88,-9,-60,-14);g.quadraticCurveTo(-48,-53,-10,-34);g.quadraticCurveTo(22,-68,45,-22);g.quadraticCurveTo(80,-26,87,5);g.quadraticCurveTo(59,22,-81,11);g.fill();g.restore()}
