  const bounds=pupilBounds();
  const bw=Math.max(1,bounds.right-bounds.left),bh=Math.max(1,bounds.bottom-bounds.top);
  const gap=Math.max(9,Math.min(32,width*.024,height*.035));
  const top=Math.min(height-gap-1,observationTop+gap),bottom=height-gap;
  const zoom=Math.min(fallback?1.78:1.62,(width-2*gap)/bw,(bottom-top)/bh);
