function updateFlatView(){
 const b=overviewFallbackBox(),cx=b.x+b.w*.5,cy=b.y+b.h*.53;
 const local=new DOMMatrix(), yaw=orbit.yaw, pitch=orbit.pitch;
 local.m11=Math.cos(yaw*.88);local.m12=Math.sin(yaw)*.23;
 local.m21=-Math.sin(yaw)*.20;local.m22=1+pitch*.54;
 local.m14=-Math.sin(yaw)/(b.w*1.55);local.m24=-pitch/(b.h*1.8);
 flatView=new DOMMatrix().translate(cx,cy).multiply(local).translate(-cx,-cy);
 flatInverse=flatView.inverse();
}
function mapFlat(matrix,x,y){
 const p=matrix.transformPoint({x,y,z:0,w:1});
 return {x:p.x/p.w,y:p.y/p.w};
}
function fallbackPoint(u,v,framed=true){
 const b=overviewFallbackBox(),p=mapFlat(flatView,b.x+u*b.w,b.y+v*b.h);
 return framed?{x:p.x*framing.scale+framing.x,y:p.y*framing.scale+framing.y}:p;
}
function paintFallbackCorner(fold,tile,edge){
 fold.hidden=!!motion||!tile?.sheet;
 if(fold.hidden)return;
 const b=overviewFallbackBox(),index=Math.round(clamp((edge.bend-.82)/(2.75-.82))*(tile.count-1));
 if(fold._tile!==tile){
  fold._tile=tile;
  fold.style.backgroundImage='url("'+tile.sheet+'")';
  fold.style.backgroundSize=(tile.count*100)+'% 100%';
 }
 Object.assign(fold.style,{
  left:(b.x+b.w*tile.left)+'px',top:(b.y-sceneInset+b.h*tile.top)+'px',
  width:(b.w*tile.width)+'px',height:(b.h*tile.height)+'px',
  backgroundPosition:(index/(tile.count-1)*100)+'% 0'
 });
}

let lastFallback=-1, fallbackImg, fallbackPicks, fallbackPupilBounds;
async function loadFallbackPicks(){
 const image=new Image();image.src=COMPAT.pickMap;
 await image.decode();
 const ctx=canvas(image.width,image.height).getContext('2d',{willReadFrequently:true});
 ctx.drawImage(image,0,0);
 fallbackPicks=ctx.getImageData(0,0,image.width,image.height);
 const {width:w,height:h,data}=fallbackPicks;
 const pupils=new Set(COMPAT.pickKeys.map((key,i)=>key==='teacher'?0:i+1).filter(Boolean));
 let left=w,right=0,top=h,bottom=0;
 for(let y=0;y<h;y++)for(let x=0;x<w;x++){
  if(!pupils.has(data[(y*w+x)*4]))continue;
  left=Math.min(left,x);right=Math.max(right,x+1);top=Math.min(top,y);bottom=Math.max(bottom,y+1);
 }
 fallbackPupilBounds={left:left/w,right:right/w,top:top/h,bottom:bottom/h};
}
function setupFallback(){
 const wrap=document.createElement('div');wrap.id='fallback';wrap.className='fallback';
 fallbackImg=new Image();fallbackImg.draggable=false;fallbackImg.alt='紙片書展開過程';
 fallbackPlane=document.createElement('div');fallbackPlane.style.cssText='position:absolute;inset:0;transform-origin:0 0';
 fallbackFold=document.createElement('div');fallbackFold.style.cssText='position:absolute;pointer-events:none;background-repeat:no-repeat';
 fallbackDesk=new Image();fallbackDesk.alt='';fallbackDesk.draggable=false;
 fallbackDesk.style.cssText='position:absolute;inset:auto;object-fit:fill;pointer-events:none';
 fallbackNextFold=fallbackFold.cloneNode(false);
 fallbackPlane.append(fallbackDesk,fallbackImg,fallbackFold,fallbackNextFold);wrap.append(fallbackPlane);$('stage').prepend(wrap);
 $('cv').hidden=true;
}
function overviewFallbackBox(){
 const scale=Math.min(width/COMPAT.width,(height-sceneInset)/COMPAT.height);
 const w=COMPAT.width*scale,h=COMPAT.height*scale;
 return {x:(width-w)/2,y:sceneInset+(height-sceneInset-h)/2,w,h};
}
function renderFallback(){
 const n=Math.round(progress*(COMPAT.frames.length-1));
 const speaker=glowForPhase();
 const frameId=observingPupils()?'observe':speaker||n;
 if(frameId!==lastFallback){
  lastFallback=frameId;
  fallbackImg.src=frameId==='observe'?COMPAT.observationFrame:speaker?COMPAT.speakerFrames[speaker]:COMPAT.frames[n];
  fallbackDesk.src=COMPAT.deskFrames[n];
 }
 const b=overviewFallbackBox();
 Object.assign(fallbackDesk.style,{left:(b.x-b.w)+'px',top:(b.y-sceneInset-3*b.h)+'px',
  width:(3*b.w)+'px',height:(7*b.h)+'px'});
 for(const [key,[u,v]] of Object.entries(COMPAT.coords)){
  const b=buttons[key],p=fallbackPoint(u,v);
  b.style.left=p.x+'px';b.style.top=p.y+'px';b.hidden=progress<.985||!!motion;
 }
}
function fallbackHit(x,y){
 if(motion||progress<.985)return null;
 const f=framing,unwarped=mapFlat(flatInverse,(x-f.x)/f.scale,(y-f.y)/f.scale);
 x=unwarped.x;y=unwarped.y;
 const box=overviewFallbackBox(),px=Math.floor((x-box.x)/box.w*fallbackPicks.width),py=Math.floor((y-box.y)/box.h*fallbackPicks.height);
 if(px>=0&&py>=0&&px<fallbackPicks.width&&py<fallbackPicks.height){
  const id=fallbackPicks.data[(py*fallbackPicks.width+px)*4];
  if(id)return COMPAT.pickKeys[id-1];
 }
 let best=null,min=1;
 for(const [key,[u,v,h]] of Object.entries(COMPAT.coords)){
  const dx=(x-(box.x+u*box.w))/Math.max(23,h*.45*box.h),dy=(y-(box.y+v*box.h))/Math.max(24,h*.64*box.h);
  const distance=dx*dx+dy*dy;if(distance<min){min=distance;best=key}
 }
 return best
}
function touchButtons(){
 // Some whiteboards suppress the compatibility click immediately after a swipe.
 let pressed=null,last=null;
 document.addEventListener('pointerdown',e=>{
  if(!e.isPrimary)return;
  last=null;pressed=null;
  if(e.pointerType==='mouse')return;
  const button=e.target.closest('button');pressed=button&&!button.matches('.book-corner')?{button,x:e.clientX,y:e.clientY,id:e.pointerId}:null
 },true);
 document.addEventListener('pointercancel',()=>{pressed=null;last=null},true);
 document.addEventListener('pointerup',e=>{
  if(!pressed||pressed.id!==e.pointerId)return;
  const start=pressed;pressed=null;
  if(start.button.disabled||e.target.closest('button')!==start.button||Math.hypot(e.clientX-start.x,e.clientY-start.y)>14)return;
  last={id:e.pointerId,x:e.clientX,y:e.clientY};start.button.click()
 },true);
 document.addEventListener('click',e=>{
  // Loading a paper scene can delay the native click until a different control is under the finger.
  // Each new pointer press clears this record, so only the already handled tap is consumed.
  if(e.isTrusted&&e.detail>0&&last&&(e.pointerId===last.id||Math.hypot(e.clientX-last.x,e.clientY-last.y)<15)){
   last=null;e.preventDefault();e.stopImmediatePropagation()
  }
 },true)
}


function bindAudioPanel(){
 const panel=$('audioPanel'),button=$('audioSettings');
 function position(){
  if(panel.hidden)return;
  const anchor=button.getBoundingClientRect();
  panel.style.top=Math.round(anchor.bottom+8)+'px';
  panel.style.left=Math.max(8,Math.min(innerWidth-panel.offsetWidth-8,anchor.right-panel.offsetWidth))+'px';
 }
 function close(restoreFocus){
  panel.hidden=true;button.setAttribute('aria-expanded','false');
  if(restoreFocus)button.focus({preventScroll:true});
 }
 button.onclick=()=>{
  readerSound.play('tap');
  if(!panel.hidden){close(true);return;}
  panel.hidden=false;button.setAttribute('aria-expanded','true');position();
  $('musicLevel').focus({preventScroll:true});
 };
 $('closeAudio').onclick=()=>close(true);
 document.addEventListener('pointerdown',e=>{
  if(!panel.hidden&&!panel.contains(e.target)&&!button.contains(e.target))close(false);
 },true);
 document.addEventListener('focusin',e=>{
  if(!panel.hidden&&!panel.contains(e.target)&&e.target!==button)close(false);
 });
 document.addEventListener('keydown',e=>{
  if(e.key==='Escape'&&!panel.hidden){e.preventDefault();close(true);}
 });
 window.addEventListener('resize',position);
}
function bindOriginalComparison(){
 const dialog=$('comparison'), scan=$('scan'), title=$('comparisonTitle').lastChild;
 const pager=$('originalPager'), prev=$('originalPrev'), next=$('originalNext');
 const picnicAlt='孔老師和六位同學在草地上野餐。';
 const leaves=[
  ['封面',ASSET.cover,'窗邊的小男孩托着下巴，上方是書名《長大以後做甚麼》。'],
  ['第 2–3 頁',ASSET.scan,picnicAlt],
  ['第 4–5 頁',ORIGINAL_EXTRAS[4],'小貢想做老師，孔老師接着問樂樂的理想。'],
  ['第 6–7 頁',ORIGINAL_EXTRAS[6],'樂樂想做小丑，東東說自己喜歡吃東西。'],
  ['第 8–9 頁',ORIGINAL_EXTRAS[8],'東東在廚房煮食，麗麗說她喜歡打扮。'],
  ['第 10–11 頁',ORIGINAL_EXTRAS[10],'麗麗想做美容師，小夢說她常常發白日夢。'],
  ['第 12–13 頁',ORIGINAL_EXTRAS[12],'小夢想做漫畫家，小美還在想自己的將來。'],
  ['第 14–15 頁',LATER_ART.scan14,'同學們坐在旋轉杯裏，小美希望永遠做大家的朋友。'],
  ['第 16–17 頁',LATER_ART.scan16,'小貢問孔老師小時候有甚麼理想。'],
  ['第 18–19 頁',LATER_ART.scan18,'孔老師和同學坐在郊外，談起自己想當老師的心願。'],
  ['第 20–21 頁',LATER_ART.scan20,'同學們拍手說，孔老師的願望實現了！'],
  ['第 22 頁',ORIGINAL_EXTRAS[22],'五位同學以想像中的職業造型聚在一起。'],
  ['封底',ORIGINAL_EXTRAS.back,'藍色封底上印着出版社資料和條碼。']
 ];
 let index=null;
 function showLeaf(i){
  const [label,src,description]=leaves[i];
  index=i;scan.src=src;scan.alt='原書'+label+'。'+description;title.textContent='原書對照 · '+label;
  prev.disabled=i===0;next.disabled=i===leaves.length-1;
  $('originalCount').textContent=(i+1)+' / '+leaves.length;
 }
 function turn(delta){
  if(index===null)return;
  const i=index+delta;if(i<0||i>=leaves.length)return;
  const focused=document.activeElement;
  showLeaf(i);readerSound.play('page');
  if(focused===next&&next.disabled)prev.focus({preventScroll:true});
  if(focused===prev&&prev.disabled)next.focus({preventScroll:true});
 }
 prev.onclick=()=>turn(-1);next.onclick=()=>turn(1);
 dialog.addEventListener('keydown',e=>{
  if(e.key!=='ArrowLeft'&&e.key!=='ArrowRight')return;
  e.stopPropagation();e.preventDefault();
  if(!e.repeat)turn(e.key==='ArrowLeft'?-1:1);
 });
 $('original').onclick=()=>{
  if(dialog.open)return;
  const cover=state()==='closed'&&!careerActivity.active&&!lokChapter.active;
  index=null;
  if(cover)showLeaf(0);
  else if(laterBook.has(lokChapter.page))laterBook.finishLine();
  else if(tungSpread.active)tungSpread.finishLine();
  else if(lokChapter.active)lokChapter.finishLine();
  else if(lokSpread.active)lokSpread.finishLine();
  else if(classroom.active)classroom.finishLine();
  else{
   finishDialogue();scan.src=ASSET.scan;scan.alt='原書第 2 至 3 頁。'+picnicAlt;
   title.textContent='原書對照 · 第 2–3 頁';
  }
  pager.hidden=!cover;dialog.classList.toggle('browse-original',cover);
  readerSound.play('tap');dialog.showModal();
 };
 $('dismiss').onclick=()=>{readerSound.play('tap');dialog.close();};
 dialog.onclick=e=>{if(e.target===dialog)dialog.close();};
 dialog.addEventListener('close',()=>{
  if(dialog.open)return;
  if(index!==null){showLeaf(0);index=null;}
  pager.hidden=true;dialog.classList.remove('browse-original');
 });
 scan.src=ASSET.scan;
}
function setupUI(){
 touchButtons();
 readerSound=makeReaderSound(SOUND_CLIPS,makeVolumeControl('sound','互動音效',50,false));
 const score=makeBookMusic($('readingMusic'),$('exploreMusic'),makeVolumeControl('music','背景配樂',50,true));
 setMusicActive=score.setActive;
 const classroomGame=$('deskAdventure'),chapter=$('lokChapter'),later=$('laterRoot');
 function syncScore(){
   const inGame=chapter.hidden ? !classroomGame.hidden : !later.hidden&&later.dataset.type==='game';
   score.setExploring(inGame);
 }
 // A contents jump can open several parent spreads in the same turn. Use the final visible page.
 const scoreObserver=new MutationObserver(syncScore);
 for(const node of [classroomGame,chapter,later])scoreObserver.observe(node,{attributes:true,attributeFilter:['hidden','data-type']});
 syncScore();
 bindAudioPanel();bookContents.bind();
 $('coverNext').onclick=advanceCover;
 careerActivity.bind();classroom.bind();deskAdventure.bind();lokChapter.bind();
 $('paper').addEventListener('keydown',e=>{
  if(printJob&&(e.key==='Enter'||e.key===' ')){e.preventDefault();finishDialogue();}
 });
 document.addEventListener('visibilitychange',()=>{if(document.hidden)finishDialogue();});
 window.addEventListener('pagehide',finishDialogue);
 for(const [key,name] of Object.entries(people)){
  const b=document.createElement('button');
  b.type='button';b.className='character';writeNames(b,name);
  b.setAttribute('aria-label','點選'+name);
  b.setAttribute('aria-controls','paper guide');
  b.hidden=true;b.onclick=()=>choose(key,b.matches(':focus-visible'));
  $('targets').append(b);buttons[key]=b;
  if(hasDialogue(key)){
   const el=document.createElement('div'),front=document.createElement('span');
   el.className='name-stand';el.hidden=true;el.dataset.person=key;
   writeNames(front,name);el.append(front);$('nameStands').append(el);nameStands.set(key,el);
  }
 }
 $('bestView').onclick=()=>laterBook.has(lokChapter.page)?laterBook.bestView():tungSpread.active?tungSpread.bestView():lokChapter.active?lokChapter.bestView():lokSpread.active?lokSpread.bestView():classroom.active?classroom.bestView():toggleBestView();
 for(const [id,delta] of [['zoomOut',-10],['zoomIn',10],['zoomHome',0]]){
  $(id).onclick=()=>{
   readerSound.play('tap');
   if(classroom.active)classroom.changeZoom(delta?classroom.zoom+delta:100);
   else setZoom(delta?manualZoom+delta:100);
  };
 }
 setZoom(100);
 $('turn').onclick=()=>turnByReader((motion?motion.to:progress)>=.5?0:1);$('stepBack').onclick=previousStep;
 $('advance').onclick=()=>{
  if(state()!=='open')return;
  const keyboard=$('advance').matches(':focus-visible');
  if(phase==='answer'&&pupilFocus>0)return;
  if(phase!=='teacher' && phase!=='answer')return;
  readerSound.play('tap');
  showStep(phase==='teacher'?'observe':'discuss',keyboard);
 };
 bindOriginalComparison();
 $('advance').addEventListener('pointerdown',()=>readingBird?.press(true));
 document.addEventListener('pointerup',()=>readingBird?.press(false));
 document.addEventListener('pointercancel',()=>readingBird?.press(false));
 const syncBird=()=>readingBird?.sync(state()==='open');
 document.addEventListener('visibilitychange',syncBird);
 new MutationObserver(syncBird).observe($('comparison'),{attributes:true,attributeFilter:['open']});
 $('fullBtn').onclick=async()=>{readerSound.play('tap');try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{$('fullBtn').title='此瀏覽器請用 F11 進入全螢幕'}};
 document.addEventListener('fullscreenchange',()=>{
  const btn=$('fullBtn'), active=Boolean(document.fullscreenElement);
  btn.title=active?'離開全螢幕':'進入全螢幕';
  btn.setAttribute('aria-label',btn.title);
  btn.querySelector('use').setAttribute('href',active?'#exit-full':'#full');
  fit();
 });
 document.addEventListener('keydown',e=>{if(!ready||lokChapter.active||deskAdventure.active||$('comparison').open||!$('audioPanel').hidden)return;if(classroom.active){
  if(e.shiftKey&&e.key.startsWith('Arrow')){
   const angles={ArrowLeft:[-4,0],ArrowRight:[4,0],ArrowUp:[0,4],ArrowDown:[0,-4]}[e.key];
   if(angles){e.preventDefault();classroom.rotate(...angles);}
  }else if(e.key==='ArrowLeft'&&!e.repeat){e.preventDefault();classroom.leave();}
  return;
 }
 if(careerActivity.active){
  if(e.key==='ArrowRight'&&!e.shiftKey&&!e.repeat){e.preventDefault();classroom.enter();}
  else if(e.key==='ArrowLeft'&&!e.shiftKey&&!e.repeat){e.preventDefault();careerActivity.returnToPicnic();}
  return;
 }
 if(e.key==='ArrowRight'&&!e.shiftKey&&!e.repeat&&state()==='open'){
  e.preventDefault();careerActivity.show();return;
 }
 if(e.shiftKey&&e.key.startsWith('Arrow')){
  e.preventDefault();
  const delta={ArrowLeft:[-.09,0],ArrowRight:[.09,0],ArrowUp:[0,.055],ArrowDown:[0,-.055]}[e.key];
  if(delta)rotateView(orbit.yaw+delta[0],orbit.pitch+delta[1]);
  return;
 }if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const target=Number(e.key==='ArrowRight');if(!e.repeat && (motion?motion.to:progress)!==target)turnByReader(target)}});
 showStep('narration')
}
async function init(){
 setupUI();
 // Measure the paper slips after the embedded font has loaded.
 const paperFont = document.fonts.load('400 32px "Huninn"').catch(error => {
  console.warn('Paper font could not be loaded', error);
 });
 await Promise.all(Object.entries(ASSET).map(async([k,url])=>{const im=new Image();im.src=url;await im.decode();images[k]=im}));
 await paperFont;
 try{setup3D()}catch(error){console.warn('2D reading mode',error);fallback=true;setupFallback();await loadFallbackPicks()}
 readingBird=makeReadingBird($('perchedBird'),images.companion,()=>!careerActivity.active&&!$('comparison').open&&state()==='open');
 coverBird=makeReadingBird($('coverBird'),images.companion,coverBirdVisible);
 coverBird.setPose(coverPoses[coverStep]);
 const syncCoverBird=()=>coverBird.sync(coverBirdVisible());
 const coverVisibility=new MutationObserver(syncCoverBird);
 for(const modal of [$('contentsDialog'),$('comparison')])coverVisibility.observe(modal,{attributes:true,attributeFilter:['open']});
 coverVisibility.observe(document.body,{attributes:true,attributeFilter:['class']});
 document.addEventListener('visibilitychange',syncCoverBird);
 ready=true;const observer=new ResizeObserver(fit);observer.observe($('coverBookSpace'));observer.observe($('stage'));observer.observe($('companionDock'));fit();bindGestures();$('load').hidden=true;$('contentsButton').disabled=false;
 const bookmark={'#lok-cards':'cards','#lok-circus':'circus'}[location.hash];
 if(location.hash==='#lok-film')bookContents.changePage('play');
 else if(bookmark)lokChapter.open(bookmark);
 else if(laterBook.has(location.hash.slice(1))||['#tung-question','#tung-cards'].includes(location.hash))bookContents.changePage(location.hash.slice(1));

}
init().catch(e=>{$('load').textContent='場景未能載入。請重新開啟此 HTML 檔。';console.error(e)});

